-- 아이템 배지 형태 묘사 칸 추가와 450종 채우기 (티켓 20261113_1145)
-- 같은 아이템(item_book_id, name)의 등급 4행에 같은 값을 넣는다. 화면 엔진은 읽지 않고 어드민과 이미지 생성기만 읽는다.
begin;
alter table public.badges add column if not exists form_description text;
comment on column public.badges.form_description is '이미지용 형태 묘사(한국어). 아이템 배지만. 어드민 배지 상세와 이미지 생성기가 읽는다. 원본은 JAM 2.0 원고 6절';
update public.badges set form_description = $fd$은박지 위에 놓인 긴 나무 꼬치에 닭고기와 대파 토막이 번갈아 꿰여 있습니다. 대파 끝이 까맣게 탔고 은박지가 반쯤 펼쳐져 있습니다.$fd$ where item_book_id = 'bd92067a-a33a-5848-1be4-8866e503efd2' and name = $fd$불맛 파닭 꼬치$fd$;
update public.badges set form_description = $fd$가는 나무 막대에 염통 조각이 줄지어 꿰인 꼬치입니다. 갈색으로 구워졌고 뾰족한 끝이 조금 갈라져 있습니다.$fd$ where item_book_id = 'bd92067a-a33a-5848-1be4-8866e503efd2' and name = $fd$염통 꼬치$fd$;
update public.badges set form_description = $fd$은박지 귀퉁이에 윤기 나는 갈색 소스가 눌어붙어 있습니다. 붉은 고춧가루가 군데군데 섞였고 가장자리가 끈적하게 굳었습니다.$fd$ where item_book_id = 'bd92067a-a33a-5848-1be4-8866e503efd2' and name = $fd$매운 데리야끼 소스$fd$;
update public.badges set form_description = $fd$작은 접시에 담긴 통마늘 덩어리입니다. 껍질 한쪽이 까맣게 그을렸고 윗부분이 살짝 벌어져 있습니다.$fd$ where item_book_id = 'bd92067a-a33a-5848-1be4-8866e503efd2' and name = $fd$그을린 통마늘$fd$;
update public.badges set form_description = $fd$작은 종지에 소복이 담긴 구운 소금입니다. 알갱이가 모나고 누르스름하며 가장자리가 조금 굳어 있습니다.$fd$ where item_book_id = 'bd92067a-a33a-5848-1be4-8866e503efd2' and name = $fd$구운 소금$fd$;
update public.badges set form_description = $fd$나무 꼬치에 연노랑 은행 알이 줄지어 꿰여 있습니다. 알마다 그을린 점이 있고 맨 끝 알이 조금 흘러내려 있습니다.$fd$ where item_book_id = 'bd92067a-a33a-5848-1be4-8866e503efd2' and name = $fd$은행 꼬치$fd$;
update public.badges set form_description = $fd$뜯는 선을 따라 찢어진 얇은 비닐 포장지입니다. 삼각형 모양으로 구겨져 있고 가장자리가 반듯하게 갈라졌습니다.$fd$ where item_book_id = '03d35a22-9c9d-f537-031e-89d45895a089' and name = $fd$삼각김밥 포장지$fd$;
update public.badges set form_description = $fd$종이 접시에 놓인 비닐 포장 핫바입니다. 비닐이 팽팽하게 부풀어 있고 한쪽 끝이 살짝 찢어져 있습니다.$fd$ where item_book_id = '03d35a22-9c9d-f537-031e-89d45895a089' and name = $fd$데운 핫바$fd$;
update public.badges set form_description = $fd$접힌 자국이 선명한 네모난 메모지입니다. 펜으로 그은 줄이 여러 겹 겹쳐 있고 모서리가 닳아 있습니다.$fd$ where item_book_id = '03d35a22-9c9d-f537-031e-89d45895a089' and name = $fd$레시피 메모$fd$;
update public.badges set form_description = $fd$속이 비치지 않는 검은 비닐봉지입니다. 손잡이 매듭이 풀려 입구가 활짝 벌어져 있고 구김이 많습니다.$fd$ where item_book_id = '03d35a22-9c9d-f537-031e-89d45895a089' and name = $fd$검은 비닐봉지$fd$;
update public.badges set form_description = $fd$반으로 부러진 나무 이쑤시개입니다. 부러진 쪽 끝이 갈라져 나뭇결이 일어나 있습니다.$fd$ where item_book_id = '91696f3a-beb7-66f3-03c0-9398596ad56e' and name = $fd$부러진 이쑤시개$fd$;
update public.badges set form_description = $fd$대나무를 엮어 만든 둥근 장바구니입니다. 손잡이가 한쪽으로 기울었고 가장자리 결이 해져 보풀처럼 일었습니다.$fd$ where item_book_id = '91696f3a-beb7-66f3-03c0-9398596ad56e' and name = $fd$낡은 시장 바구니$fd$;
update public.badges set form_description = $fd$그물망 머리가 찌그러진 검은 막대형 마이크입니다. 손잡이에 감긴 테이프가 닳아 반질반질해졌습니다.$fd$ where item_book_id = '91696f3a-beb7-66f3-03c0-9398596ad56e' and name = $fd$백승리의 마이크$fd$;
update public.badges set form_description = $fd$옷핀이 달린 직사각형 플라스틱 명찰입니다. 모서리가 둥글고 겉면이 긁혀 흐릿해졌습니다.$fd$ where item_book_id = '91696f3a-beb7-66f3-03c0-9398596ad56e' and name = $fd$명찰$fd$;
update public.badges set form_description = $fd$냄비 뚜껑 위에 접힌 작은 종이쪽지가 붙어 있습니다. 귀퉁이가 들떠 있고 접힌 선마다 기름 얼룩이 배었습니다.$fd$ where item_book_id = '91696f3a-beb7-66f3-03c0-9398596ad56e' and name = $fd$냄비 뚜껑 쪽지$fd$;
update public.badges set form_description = $fd$둥근 접시에 담긴 두툼한 녹두빈대떡입니다. 가장자리가 노릇하게 부풀었고 가운데가 칼로 갈라져 있습니다.$fd$ where item_book_id = 'fb3adceb-50c2-9306-ea19-8fd49637d27f' and name = $fd$녹두빈대떡$fd$;
update public.badges set form_description = $fd$가운데가 반투명하게 번진 흰 종이 냅킨입니다. 네모로 접혔다 펴진 선이 남았고 둥근 기름 얼룩이 찍혀 있습니다.$fd$ where item_book_id = 'fb3adceb-50c2-9306-ea19-8fd49637d27f' and name = $fd$기름 튄 냅킨$fd$;
update public.badges set form_description = $fd$뚜껑 없는 낡은 나무 상자에 사과가 가득 담겨 있습니다. 양옆에 손잡이 구멍이 뚫렸고 모서리가 갈라졌습니다.$fd$ where item_book_id = 'fb3adceb-50c2-9306-ea19-8fd49637d27f' and name = $fd$재료 상자$fd$;
update public.badges set form_description = $fd$붉은 다대기가 눌어붙은 쇠숟가락입니다. 오목한 부분에 윤이 나고 손잡이 끝이 살짝 휘었습니다.$fd$ where item_book_id = '88aecafb-04e3-5a28-68ea-396f3c632fe0' and name = $fd$다대기 묻은 숟가락$fd$;
update public.badges set form_description = $fd$작은 종지에 붉은 깍두기 국물이 반쯤 담겨 있습니다. 고춧가루가 바닥에 가라앉았고 종지가 한쪽으로 기울었습니다.$fd$ where item_book_id = '88aecafb-04e3-5a28-68ea-396f3c632fe0' and name = $fd$깍두기 국물$fd$;
update public.badges set form_description = $fd$뚜껑이 살짝 열린 은색 스테인리스 밥공기입니다. 뚜껑 안쪽에 물방울이 맺혔고 가장자리가 조금 찌그러졌습니다.$fd$ where item_book_id = '88aecafb-04e3-5a28-68ea-396f3c632fe0' and name = $fd$스테인리스 밥공기$fd$;
update public.badges set form_description = $fd$구겨진 흰 물티슈입니다. 한쪽 귀퉁이에 붉은 국물 자국이 묻어 있고 전체가 눅눅하게 늘어져 있습니다.$fd$ where item_book_id = '88aecafb-04e3-5a28-68ea-396f3c632fe0' and name = $fd$입 닦은 물티슈$fd$;
update public.badges set form_description = $fd$반으로 갈라진 붕어빵 두 쪽이 접시에 나란히 놓여 있습니다. 머리 쪽 속은 붉은 팥이고 꼬리 쪽 속은 노란 크림입니다.$fd$ where item_book_id = '99553671-7ec6-08bc-56c0-af12aa326b2b' and name = $fd$팥 반 슈크림 반 붕어빵$fd$;
update public.badges set form_description = $fd$작은 접시에 쌓인 매실 씨 무더기입니다. 씨마다 갈색 주름이 깊고 일부에 하얀 단물 결정이 말라붙었습니다.$fd$ where item_book_id = '3b22f8f3-4fb6-6719-afb1-4f1c3f74093d' and name = $fd$매실 씨 한 줌$fd$;
update public.badges set form_description = $fd$종이 위에 놓인 배가 불룩한 붕어빵입니다. 옆구리로 노란 크림이 삐져나왔고 비늘 무늬가 또렷하게 찍혀 있습니다.$fd$ where item_book_id = '99553671-7ec6-08bc-56c0-af12aa326b2b' and name = $fd$슈크림 붕어빵$fd$;
update public.badges set form_description = $fd$긴 쇠집게이며 끝이 붕어 몸통 폭만큼 둥글게 휘어 있습니다. 손잡이 쪽 도금이 군데군데 벗겨졌습니다.$fd$ where item_book_id = '99553671-7ec6-08bc-56c0-af12aa326b2b' and name = $fd$붕어빵 집게$fd$;
update public.badges set form_description = $fd$뚜껑이 열린 흰 플라스틱 반죽 통입니다. 안의 묽은 반죽이 한쪽으로 기울었고 테두리에 반죽이 말라붙었습니다.$fd$ where item_book_id = '99553671-7ec6-08bc-56c0-af12aa326b2b' and name = $fd$반죽 통$fd$;
update public.badges set form_description = $fd$끝이 닳아 보풀이 인 회색 털장갑입니다. 엄지 쪽에 반죽 얼룩이 말라붙어 딱딱하게 굳었습니다.$fd$ where item_book_id = '99553671-7ec6-08bc-56c0-af12aa326b2b' and name = $fd$털장갑$fd$;
update public.badges set form_description = $fd$종이에 싸인 작은 타원형 계란빵입니다. 한가운데 달걀이 통째로 박혀 노른자가 보이고 가장자리가 갈색으로 눌었습니다.$fd$ where item_book_id = '99553671-7ec6-08bc-56c0-af12aa326b2b' and name = $fd$계란빵$fd$;
update public.badges set form_description = $fd$비누 상자만 한 네모난 플라스틱 라디오입니다. 안테나가 한쪽으로 기울었고 다이얼 옆에 기름 얼룩이 번졌습니다.$fd$ where item_book_id = 'fb3adceb-50c2-9306-ea19-8fd49637d27f' and name = $fd$주방 구석의 라디오$fd$;
update public.badges set form_description = $fd$물이 빠진 남색 면 앞치마입니다. 앞자락에 국물 튄 자국이 겹겹이 말랐고 허리끈 한쪽이 풀려 늘어져 있습니다.$fd$ where item_book_id = '3b22f8f3-4fb6-6719-afb1-4f1c3f74093d' and name = $fd$앞치마$fd$;
update public.badges set form_description = $fd$투명한 유리컵에 옅은 호박빛 물이 반쯤 담겨 있습니다. 바닥의 청이 덜 풀렸고 컵 가장자리에 물방울 자국이 있습니다.$fd$ where item_book_id = '3b22f8f3-4fb6-6719-afb1-4f1c3f74093d' and name = $fd$매실청 탄 물컵$fd$;
update public.badges set form_description = $fd$하얀 사발에 담긴 꼬불꼬불한 라면 면발 덩어리입니다. 물기가 빠져 노란 면이 용수철처럼 말렸고 일부가 사발 밖으로 늘어졌습니다.$fd$ where item_book_id = 'e42446a1-d63f-f089-5fc0-c60552996d31' and name = $fd$꼬들한 라면 면발$fd$;
update public.badges set form_description = $fd$작은 그릇에 담긴 연갈색 들깨가루 더미입니다. 기름이 배어 군데군데 뭉쳤고 윗면이 숟가락 자국으로 패였습니다.$fd$ where item_book_id = '88aecafb-04e3-5a28-68ea-396f3c632fe0' and name = $fd$들깨가루$fd$;
update public.badges set form_description = $fd$가운데부터 쪼개진 나무젓가락 두 짝입니다. 한쪽은 반듯하고 다른 쪽은 살짝 휘었으며 갈라진 끝에 거스러미가 일었습니다.$fd$ where item_book_id = '7ecbc840-6167-03a3-95b7-acca945951b1' and name = $fd$갈라진 나무젓가락$fd$;
update public.badges set form_description = $fd$흰 사기 국그릇에 맑은 어묵 국물이 담겨 있습니다. 무 토막이 떠 있고 그릇 테두리가 조금 깨졌습니다.$fd$ where item_book_id = '7ecbc840-6167-03a3-95b7-acca945951b1' and name = $fd$들고 나간 어묵 국물$fd$;
update public.badges set form_description = $fd$자판기 옆면에서 벗겨진 스티커 조각입니다. 한쪽 귀퉁이가 말려 올라갔고 색이 바래 표면이 흐릿해졌습니다.$fd$ where item_book_id = 'bf20a6e1-d3e3-989c-b2db-795287c711d6' and name = $fd$오아시스 스티커$fd$;
update public.badges set form_description = $fd$화면이 아래로 엎어진 직사각형 휴대폰입니다. 케이스 모서리가 닳았고 뒷면에 지문이 뿌옇게 앉았습니다.$fd$ where item_book_id = '7ecbc840-6167-03a3-95b7-acca945951b1' and name = $fd$엎어 둔 휴대폰$fd$;
update public.badges set form_description = $fd$둥근 접시에 소복이 담긴 볶음밥입니다. 밥알에 윤기가 돌고 한가운데가 숟가락 자국으로 갈라져 있습니다.$fd$ where item_book_id = 'e42446a1-d63f-f089-5fc0-c60552996d31' and name = $fd$기름진 볶음밥$fd$;
update public.badges set form_description = $fd$둥근 머리에 마른 국물 자국이 붙은 쇠숟가락입니다. 손잡이가 한쪽으로 휘었고 비스듬히 누워 있습니다.$fd$ where item_book_id = '7ecbc840-6167-03a3-95b7-acca945951b1' and name = $fd$날아간 숟가락$fd$;
update public.badges set form_description = $fd$뚜껑이 젖혀진 네모난 플라스틱 도시락입니다. 칸이 나뉘어 있고 칸마다 반찬 물기가 마른 동그란 자국이 남았습니다.$fd$ where item_book_id = '03d35a22-9c9d-f537-031e-89d45895a089' and name = $fd$차가운 도시락$fd$;
update public.badges set form_description = $fd$옆으로 쓰러진 등받이 의자입니다. 등받이가 삐딱하게 기울었고 다리 끝 고무가 닳아 있습니다.$fd$ where item_book_id = '7ecbc840-6167-03a3-95b7-acca945951b1' and name = $fd$넘어진 의자$fd$;
update public.badges set form_description = $fd$접시에 놓인 막대 핫도그입니다. 한쪽 끝이 둥글게 베어져 있고 튀김옷 위에 케첩이 말라붙었습니다.$fd$ where item_book_id = '7ecbc840-6167-03a3-95b7-acca945951b1' and name = $fd$한 입 핫도그$fd$;
update public.badges set form_description = $fd$둥근 접시에 담긴 떡볶이 덩어리입니다. 붉은 소스가 한쪽 가장자리로 쏠렸고 가래떡 겉면에 윤기가 올라 있습니다.$fd$ where item_book_id = '7ecbc840-6167-03a3-95b7-acca945951b1' and name = $fd$매콤달콤 떡볶이$fd$;
update public.badges set form_description = $fd$종이 위에 놓인 큼직한 둥근 뻥튀기 과자입니다. 부푼 알갱이 사이에 가는 틈이 보이고 가장자리가 조금 부서졌습니다.$fd$ where item_book_id = '7ecbc840-6167-03a3-95b7-acca945951b1' and name = $fd$길거리 뻥튀기$fd$;
update public.badges set form_description = $fd$구겨졌다 펴진 은박지입니다. 접힌 선이 격자처럼 남았고 군데군데 기름 자국과 그을음이 번졌습니다.$fd$ where item_book_id = 'bd92067a-a33a-5848-1be4-8866e503efd2' and name = $fd$불향 나는 은박지$fd$;
update public.badges set form_description = $fd$손전등만 한 검은 몸통의 가스 토치입니다. 점화 버튼이 반들반들 닳았고 노즐 끝이 그을려 있습니다.$fd$ where item_book_id = 'bd92067a-a33a-5848-1be4-8866e503efd2' and name = $fd$가스 토치$fd$;
update public.badges set form_description = $fd$뚜껑이 반쯤 열린 투명한 플라스틱 양념통입니다. 속이 비었고 바닥에 붉은 가루가 얇게 눌어붙었습니다.$fd$ where item_book_id = 'bd92067a-a33a-5848-1be4-8866e503efd2' and name = $fd$빈 양념통$fd$;
update public.badges set form_description = $fd$작은 접시에 담긴 둥근 타코야끼 덩어리입니다. 얹힌 가다랑어포가 납작하게 가라앉았고 소스 표면이 굳었습니다.$fd$ where item_book_id = '7ecbc840-6167-03a3-95b7-acca945951b1' and name = $fd$식어버린 타코야끼$fd$;
update public.badges set form_description = $fd$명함만 한 얇은 종이 번호표입니다. 한쪽 모서리가 돌돌 말려 있고 전체에 구김이 졌습니다.$fd$ where item_book_id = '03d35a22-9c9d-f537-031e-89d45895a089' and name = $fd$웨이팅 번호표$fd$;
update public.badges set form_description = $fd$속이 빈 종이 컵라면 용기입니다. 안쪽 물 선을 따라 붉은 띠가 이어지고 뚜껑이 반쯤 말려 올라가 있습니다.$fd$ where item_book_id = '03d35a22-9c9d-f537-031e-89d45895a089' and name = $fd$매운 컵라면$fd$;
update public.badges set form_description = $fd$동그란 은박 뚜껑입니다. 가운데가 빨대에 뚫려 구멍이 났고 둘레에 노란 우유 자국이 말라 있습니다.$fd$ where item_book_id = '03d35a22-9c9d-f537-031e-89d45895a089' and name = $fd$바나나 우유 뚜껑$fd$;
update public.badges set form_description = $fd$접시 구석에 놓인 순대 조각 덩어리입니다. 가장자리가 말라 껍질이 오그라들었고 이쑤시개가 꽂혀 있습니다.$fd$ where item_book_id = '91696f3a-beb7-66f3-03c0-9398596ad56e' and name = $fd$남은 순대$fd$;
