update public.badges set form_description = $fd$단추만 한 네모 틀에 필름 한 컷이 끼워진 슬라이드입니다. 테두리는 하얗고 가운데가 주황에서 보라로 번졌습니다.$fd$ where item_book_id = 'ad1a2ef7-4499-0773-f0c8-ba31e96087f2' and name = $fd$노을빛 슬라이드 필름$fd$;
