update public.badges set form_description = $fd$여러 번 접은 얇은 종이 서류입니다. 빽빽한 잔줄 무늬가 가득하고 아래쪽에 은색 둥근 도장 자국이 있으며 접힌 선이 하얗게 닳았습니다.$fd$ where item_book_id = '9232c1ce-cbc6-d314-4739-08b4ceae84c5' and name = $fd$영문 보증서$fd$;
