update public.badges set form_description = $fd$삼으로 꼰 연갈색 노끈이 느슨하게 풀려 놓여 있습니다. 연필 굵기이고 끝에 매듭이 남았으며 끝 올이 갈라졌습니다.$fd$ where item_book_id = '9232c1ce-cbc6-d314-4739-08b4ceae84c5' and name = $fd$풀어 둔 노끈$fd$;
update public.badges set form_description = $fd$속이 빈 골판지 상자입니다. 뚜껑 날개가 벌어져 있고 바닥에 테이프를 뜯은 자국이 있으며 모서리가 눌려 있습니다.$fd$ where item_book_id = '9232c1ce-cbc6-d314-4739-08b4ceae84c5' and name = $fd$빈 상자$fd$;
update public.badges set form_description = $fd$신용카드 크기의 흰 플라스틱 카드입니다. 때가 타서 누렇고 모서리가 닳아 둥글어졌으며 귀퉁이가 살짝 휘었습니다.$fd$ where item_book_id = '31b5587e-d58e-3630-06d9-8a7665ba2ad0' and name = $fd$교통카드$fd$;
update public.badges set form_description = $fd$체크무늬 얇은 담요가 네모나게 접혀 있습니다. 가장자리 올이 닳아 풀렸고 접힌 선이 하얗게 바랬습니다.$fd$ where item_book_id = '31b5587e-d58e-3630-06d9-8a7665ba2ad0' and name = $fd$좌판 깔개 담요$fd$;
update public.badges set form_description = $fd$입구를 눌러 닫는 투명하고 얇은 비닐 주머니입니다. 윗부분에 흰 띠가 감겨 있고 모서리가 구겨졌으며 지퍼 홈이 조금 늘어났습니다.$fd$ where item_book_id = '31b5587e-d58e-3630-06d9-8a7665ba2ad0' and name = $fd$지퍼백$fd$;
update public.badges set form_description = $fd$검은 플라스틱 케이스에서 둥근 유리 렌즈가 반쯤 펼쳐진 돋보기입니다. 카드 지갑보다 작고 케이스 모서리가 긁혀 있습니다.$fd$ where item_book_id = '31b5587e-d58e-3630-06d9-8a7665ba2ad0' and name = $fd$접이식 돋보기$fd$;
update public.badges set form_description = $fd$속이 꽉 찬 납작한 둥근 유리 덩어리입니다. 주먹보다 작고 투명하며 아랫면에 동그란 테가 새겨졌고 가장자리에 작은 흠집이 있습니다.$fd$ where item_book_id = '31b5587e-d58e-3630-06d9-8a7665ba2ad0' and name = $fd$유리 문진$fd$;
update public.badges set form_description = $fd$작은 바퀴가 아래에 달린 접이식 천 장바구니입니다. 천에 흙 자국이 얼룩져 있고 긴 당김대가 비스듬히 기울어 있습니다.$fd$ where item_book_id = '31b5587e-d58e-3630-06d9-8a7665ba2ad0' and name = $fd$바퀴 달린 장바구니$fd$;
update public.badges set form_description = $fd$모서리가 누렇게 뜬 얇은 책자입니다. 표지가 접혀 있고 속지에 작은 사진 칸이 바둑판처럼 나열되어 있습니다.$fd$ where item_book_id = '31b5587e-d58e-3630-06d9-8a7665ba2ad0' and name = $fd$문구 카탈로그$fd$;
update public.badges set form_description = $fd$작은 놋쇠 종입니다. 둥글게 퍼진 모양이고 노란 광이 희미하며 표면에 먼지와 푸른 녹 얼룩이 앉아 있습니다.$fd$ where item_book_id = '31b5587e-d58e-3630-06d9-8a7665ba2ad0' and name = $fd$놋쇠 종$fd$;
update public.badges set form_description = $fd$립스틱만 한 작은 유리병입니다. 안쪽에 노란 기름이 조금 남았고 뚜껑 가장자리에 쇳가루가 말라붙어 있습니다.$fd$ where item_book_id = 'eff21028-8cbc-cce2-4c88-55fdd156d94b' and name = $fd$태엽 기름병$fd$;
update public.badges set form_description = $fd$크기순으로 쇠 렌치가 꽂힌 납작한 케이스입니다. 가운데 몇 칸이 비어 있고 덮개 천의 올이 풀려 있습니다.$fd$ where item_book_id = 'eff21028-8cbc-cce2-4c88-55fdd156d94b' and name = $fd$육각렌치 세트 케이스$fd$;
update public.badges set form_description = $fd$기름이 배어 거뭇해진 헝겊이 구겨진 채 펼쳐져 있습니다. 원래 흰 면직물이라 가장자리에 흰 빛이 조금 남았고 올이 풀려 있습니다.$fd$ where item_book_id = 'eff21028-8cbc-cce2-4c88-55fdd156d94b' and name = $fd$더러운 걸레$fd$;
update public.badges set form_description = $fd$두꺼운 가죽 작업 장갑 한 켤레가 나란히 놓여 있습니다. 끝부분이 까맣게 배었고 엄지 쪽에 흰 실로 덧댄 바느질이 있습니다.$fd$ where item_book_id = 'eff21028-8cbc-cce2-4c88-55fdd156d94b' and name = $fd$정비 장갑$fd$;
update public.badges set form_description = $fd$코가 둥글고 가는 펜치입니다. 자루에 붉은 고무가 씌워져 있고 코끝에 긁힌 흠집이 있으며 벌어진 채 놓여 있습니다.$fd$ where item_book_id = 'eff21028-8cbc-cce2-4c88-55fdd156d94b' and name = $fd$열쇠고리 펜치$fd$;
update public.badges set form_description = $fd$뚜껑이 허옇게 굳은 작은 접착제 튜브입니다. 입구 가장자리에 투명한 껍질처럼 마른 본드가 겹쳐 붙어 있고 튜브 허리가 눌렸습니다.$fd$ where item_book_id = 'eff21028-8cbc-cce2-4c88-55fdd156d94b' and name = $fd$비즈 본드$fd$;
update public.badges set form_description = $fd$끝이 살짝 휜 은색 금속 핀셋입니다. 길이는 볼펜 정도이고 맞물리는 끝에 긁힌 자국이 있으며 약간 벌어져 있습니다.$fd$ where item_book_id = 'eff21028-8cbc-cce2-4c88-55fdd156d94b' and name = $fd$비즈 핀셋$fd$;
update public.badges set form_description = $fd$가장자리가 누렇게 바랜 얇고 길쭉한 종이표입니다. 파란 줄무늬가 가로로 지나가고 모서리가 접혀 있습니다.$fd$ where item_book_id = 'af74bb10-30c7-603d-c6f9-cf7f95533f58' and name = $fd$종이 버스표$fd$;
update public.badges set form_description = $fd$반으로 찢어진 감열지 표입니다. 표면이 회색으로 흐릿하게 바랬고 찢어진 가장자리가 들쭉날쭉합니다.$fd$ where item_book_id = 'af74bb10-30c7-603d-c6f9-cf7f95533f58' and name = $fd$다 쓴 영화표$fd$;
update public.badges set form_description = $fd$여러 번 접혀 납작해진 종이봉투입니다. 붕어 모양 윤곽이 접힌 선을 따라 갈라져 있고 모서리가 구겨졌습니다.$fd$ where item_book_id = 'af74bb10-30c7-603d-c6f9-cf7f95533f58' and name = $fd$접어 둔 붕어빵 봉투$fd$;
update public.badges set form_description = $fd$회색 매끈한 돌멩이입니다. 표면에 작은 구덩이 자국이 흩어져 있고 한쪽이 비스듬히 깎여 있습니다.$fd$ where item_book_id = 'af74bb10-30c7-603d-c6f9-cf7f95533f58' and name = $fd$모양이 특이한 돌멩이$fd$;
update public.badges set form_description = $fd$콩알만 한 노란 놋쇠 단추입니다. 앞면이 닳아 반짝이고 가운데에 실구멍이 뚫려 있으며 가장자리가 약간 찌그러졌습니다.$fd$ where item_book_id = 'af74bb10-30c7-603d-c6f9-cf7f95533f58' and name = $fd$빛나는 놋쇠 단추$fd$;
update public.badges set form_description = $fd$파란 플라스틱 빵 봉지 집게입니다. 납작한 아치 모양이고 날 가장자리에 금이 가 있으며 벌어진 채 놓여 있습니다.$fd$ where item_book_id = 'af74bb10-30c7-603d-c6f9-cf7f95533f58' and name = $fd$빵 봉지 집게$fd$;
update public.badges set form_description = $fd$구겨졌다 펴진 얇은 사탕 포장지입니다. 빨간 줄무늬가 가장자리를 두르고 잔주름이 가득하며 끝이 말려 있습니다.$fd$ where item_book_id = 'af74bb10-30c7-603d-c6f9-cf7f95533f58' and name = $fd$납작하게 편 사탕 포장지$fd$;
update public.badges set form_description = $fd$양철로 만든 작은 쥐 장난감입니다. 옆면에 태엽 구멍이 뚫려 있고 발끝 도금이 닳았으며 꼬리가 약간 휘었습니다.$fd$ where item_book_id = 'b2d04ee7-5749-f60d-a7c6-dfc6ffdb391d' and name = $fd$태엽 감는 장난감 쥐$fd$;
update public.badges set form_description = $fd$성냥갑만 한 작은 장난감 자동차입니다. 바퀴 한쪽이 빠져 축이 드러났고 축에 녹물이 번져 한쪽으로 기울어 있습니다.$fd$ where item_book_id = 'b2d04ee7-5749-f60d-a7c6-dfc6ffdb391d' and name = $fd$바퀴 빠진 미니카$fd$;
update public.badges set form_description = $fd$나무로 깎은 팽이입니다. 칠이 대부분 벗겨져 맨 나무가 드러났고 붉은 줄만 군데군데 남았으며 꼭지가 닳아 있습니다.$fd$ where item_book_id = 'b2d04ee7-5749-f60d-a7c6-dfc6ffdb391d' and name = $fd$색이 벗겨진 팽이$fd$;
update public.badges set form_description = $fd$나무 요요입니다. 마주 보는 원판 사이에 끊어진 줄 토막이 감겨 있고 원판의 붉은 칠이 닳았으며 기울어 놓여 있습니다.$fd$ where item_book_id = 'b2d04ee7-5749-f60d-a7c6-dfc6ffdb391d' and name = $fd$줄 끊어진 요요$fd$;
update public.badges set form_description = $fd$네모난 양철 로봇 장난감입니다. 어깨 이음새에서 한쪽 팔이 꺾여 속 철판이 갈라져 보이고 칠이 곳곳에 벗겨져 있습니다.$fd$ where item_book_id = 'b2d04ee7-5749-f60d-a7c6-dfc6ffdb391d' and name = $fd$팔이 부러진 로봇$fd$;
update public.badges set form_description = $fd$달걀만 한 둥근 오뚝이 장난감입니다. 밑이 둥글게 기울어 옆으로 누워 있고 표면 칠이 반쯤 지워졌습니다.$fd$ where item_book_id = 'b2d04ee7-5749-f60d-a7c6-dfc6ffdb391d' and name = $fd$서지 않는 오뚝이$fd$;
update public.badges set form_description = $fd$양철 로봇 장난감이 똑바로 서 있습니다. 팔다리 이음새마다 은색 땜납 자국이 점처럼 남았고 칠이 벗겨진 곳이 있습니다.$fd$ where item_book_id = 'b2d04ee7-5749-f60d-a7c6-dfc6ffdb391d' and name = $fd$수리를 마친 로봇$fd$;
update public.badges set form_description = $fd$양철로 만든 작은 프로펠러 비행기입니다. 날개 한쪽이 접혀 있고 동체의 노란 줄이 군데군데 벗겨져 남았습니다.$fd$ where item_book_id = 'b2d04ee7-5749-f60d-a7c6-dfc6ffdb391d' and name = $fd$양철 비행기$fd$;
update public.badges set form_description = $fd$네모난 양철 로봇 장난감입니다. 팔이 굳은 채 내려가 있고 이음새가 헐거워 흔들면 속에서 나사가 구르며 칠이 벗겨져 있습니다.$fd$ where item_book_id = 'b2d04ee7-5749-f60d-a7c6-dfc6ffdb391d' and name = $fd$고장 난 그대로인 한 대$fd$;
update public.badges set form_description = $fd$여러 번 접혔다 펼쳐진 종이 서류입니다. 접힌 선이 격자로 남아 있고 윗부분에 잔줄이 이어지며 모서리가 닳았습니다.$fd$ where item_book_id = '8405301c-5dfe-4e35-55f6-1d869d1a1a91' and name = $fd$입양 서약서$fd$;
update public.badges set form_description = $fd$종이 서류가 풀로 겹겹이 붙은 두툼한 묶음입니다. 가장자리가 불룩하게 부풀어 있고 모서리가 들떠 있습니다.$fd$ where item_book_id = '8405301c-5dfe-4e35-55f6-1d869d1a1a91' and name = $fd$5장 넘게 붙은 서약서$fd$;
update public.badges set form_description = $fd$똑같이 생긴 작은 인형이 포개져 놓여 있습니다. 투명 캡슐에서 나온 단단한 플라스틱이며 한쪽 귀퉁이 칠이 벗겨졌습니다.$fd$ where item_book_id = '8405301c-5dfe-4e35-55f6-1d869d1a1a91' and name = $fd$겹친 캡슐토이$fd$;
update public.badges set form_description = $fd$같은 색 띠 무늬가 담긴 엽서가 포개져 있습니다. 두꺼운 종이이고 모서리가 빳빳하며 윗장 귀퉁이가 약간 들떠 있습니다.$fd$ where item_book_id = '8405301c-5dfe-4e35-55f6-1d869d1a1a91' and name = $fd$2개가 된 한정판$fd$;
update public.badges set form_description = $fd$콩알만 한 작은 동물 모형이 모여 있습니다. 같은 재질의 단단한 플라스틱이고 귀와 꼬리 끝의 색이 벗겨졌습니다.$fd$ where item_book_id = '8405301c-5dfe-4e35-55f6-1d869d1a1a91' and name = $fd$동물 모형$fd$;
update public.badges set form_description = $fd$금속 집게가 달린 나무 클립보드입니다. 판 윗부분에 볼펜 자국이 깊게 패어 있고 모서리가 둥글게 닳았습니다.$fd$ where item_book_id = '8405301c-5dfe-4e35-55f6-1d869d1a1a91' and name = $fd$입양 클립보드$fd$;
update public.badges set form_description = $fd$반으로 갈라진 유리구슬입니다. 바깥은 매끈하고 단면에 잔금이 퍼져 있으며 가장자리가 조금 이가 빠졌습니다.$fd$ where item_book_id = '1407bbea-f57a-aa97-2dce-c6ec834bec1c' and name = $fd$깨진 유리구슬$fd$;
update public.badges set form_description = $fd$중간에서 꺾인 은색 옷핀입니다. 광택이 닳았고 부러진 끝이 갈라져 벌어져 있으며 스프링 부분이 살짝 눌렸습니다.$fd$ where item_book_id = '1407bbea-f57a-aa97-2dce-c6ec834bec1c' and name = $fd$부러진 은색 옷핀$fd$;
update public.badges set form_description = $fd$구멍이 뚫린 둥근 금속 단추입니다. 가장자리 테가 닳아 광택이 줄었고 가운데에 얕은 홈이 돌아 있습니다.$fd$ where item_book_id = '1407bbea-f57a-aa97-2dce-c6ec834bec1c' and name = $fd$반짝이는 단추$fd$;
update public.badges set form_description = $fd$콩알만 한 둥근 비즈가 쏟아져 흩어져 있습니다. 분홍, 파랑, 노랑이 섞여 있고 몇 알은 가장자리가 이가 빠졌습니다.$fd$ where item_book_id = '1407bbea-f57a-aa97-2dce-c6ec834bec1c' and name = $fd$비즈 한 줌$fd$;
update public.badges set form_description = $fd$립스틱만 한 솜 채운 천 인형입니다. 눌려 납작하게 앉아 있고 한쪽 솔기의 올이 풀려 있습니다.$fd$ where item_book_id = '1407bbea-f57a-aa97-2dce-c6ec834bec1c' and name = $fd$바꿔 온 작은 인형$fd$;
update public.badges set form_description = $fd$투명한 가는 실에 비즈가 줄지어 꿰어져 있습니다. 노랑에서 초록으로 이어지고 양쪽 끝이 매듭으로 묶였으며 실이 약간 늘어졌습니다.$fd$ where item_book_id = '1407bbea-f57a-aa97-2dce-c6ec834bec1c' and name = $fd$비즈 꿴 가는 실$fd$;
update public.badges set form_description = $fd$쇠고리 아래로 작은 인형과 비즈 줄이 늘어진 열쇠고리입니다. 비즈가 색색이고 줄 가닥이 약간 꼬여 있습니다.$fd$ where item_book_id = '1407bbea-f57a-aa97-2dce-c6ec834bec1c' and name = $fd$세상에 하나뿐인 열쇠고리$fd$;
update public.badges set form_description = $fd$콩알만 한 연보라 비즈 알입니다. 은빛 줄무늬가 감겨 있고 구멍이 아주 가늘며 표면 한쪽에 작은 흠이 있습니다.$fd$ where item_book_id = '1407bbea-f57a-aa97-2dce-c6ec834bec1c' and name = $fd$아직 쓰지 않은 한 알$fd$;
update public.badges set form_description = $fd$검은 천으로 지은 납작한 가방입니다. 겉면이 열쇠고리로 빽빽하게 덮여 천이 거의 보이지 않고 끈이 한쪽으로 늘어졌습니다.$fd$ where item_book_id = 'b8d5d84e-9819-02f8-d302-15b7cccac325' and name = $fd$검은 가방$fd$;
update public.badges set form_description = $fd$투명 아크릴 판에 둥근 별 모양이 담긴 작은 열쇠고리입니다. 귀퉁이 구멍에 은색 고리가 끼워져 있고 판 가장자리에 흠집이 났습니다.$fd$ where item_book_id = 'b8d5d84e-9819-02f8-d302-15b7cccac325' and name = $fd$아크릴 열쇠고리$fd$;
update public.badges set form_description = $fd$크기와 모양이 똑같은 작은 천 인형이 나란히 놓여 있습니다. 솔기와 색이 같고 한쪽 솔기의 올이 약간 풀렸습니다.$fd$ where item_book_id = 'b8d5d84e-9819-02f8-d302-15b7cccac325' and name = $fd$2개가 된 인형$fd$;
update public.badges set form_description = $fd$가는 천 리본입니다. 반복되는 무늬가 들어 있고 연필보다 길며 끝이 제비꼬리 모양으로 갈라져 한쪽 올이 풀렸습니다.$fd$ where item_book_id = 'b8d5d84e-9819-02f8-d302-15b7cccac325' and name = $fd$리본$fd$;
update public.badges set form_description = $fd$둥근 자수 와펜입니다. 가장자리가 촘촘한 실로 감쳐 있고 뒷면은 천이며 테두리 실이 한쪽에서 풀렸습니다.$fd$ where item_book_id = 'b8d5d84e-9819-02f8-d302-15b7cccac325' and name = $fd$와펜$fd$;
update public.badges set form_description = $fd$지퍼가 달린 납작한 천 파우치입니다. 앞면에 물결 무늬가 박혀 있고 안감은 분홍색이며 지퍼가 반쯤 열려 있습니다.$fd$ where item_book_id = 'b8d5d84e-9819-02f8-d302-15b7cccac325' and name = $fd$파우치$fd$;
update public.badges set form_description = $fd$투명 아크릴 판이 받침 홈에 꽂혀 서 있는 스탠드입니다. 판에 둥근 별 모양이 담겨 있고 받침 가장자리에 흠집이 있으며 약간 기울었습니다.$fd$ where item_book_id = 'b8d5d84e-9819-02f8-d302-15b7cccac325' and name = $fd$아크릴 스탠드$fd$;
update public.badges set form_description = $fd$빳빳한 작은 종이 꼬리표입니다. 구멍에 가는 끈이 꿰여 늘어져 있고 모서리가 둥글게 닳았습니다.$fd$ where item_book_id = 'b8d5d84e-9819-02f8-d302-15b7cccac325' and name = $fd$종이 꼬리표$fd$;
update public.badges set form_description = $fd$뚜껑에 먼지가 쌓인 낡은 종이 상자입니다. 모서리가 눌려 찌그러졌고 뚜껑이 약간 들려 있습니다.$fd$ where item_book_id = 'a92d8af5-78cc-9d19-738f-9b6897f0f6d7' and name = $fd$창고 구석의 상자$fd$;
update public.badges set form_description = $fd$흰 직사각형 지우개입니다. 각진 모서리가 새것처럼 뾰족하고 한쪽 면에 도안이 찍혀 있으며 겉 종이 띠가 조금 찢겼습니다.$fd$ where item_book_id = 'a92d8af5-78cc-9d19-738f-9b6897f0f6d7' and name = $fd$단종 지우개$fd$;
update public.badges set form_description = $fd$지퍼가 달린 납작한 천 필통입니다. 무늬가 바래지 않고 선명하며 지퍼가 반쯤 열려 있고 모서리가 살짝 눌렸습니다.$fd$ where item_book_id = 'a92d8af5-78cc-9d19-738f-9b6897f0f6d7' and name = $fd$새것 같은 필통$fd$;
update public.badges set form_description = $fd$라벨이 노랗게 바랜 작은 유리 잉크병입니다. 검은 잉크가 반쯤 차 있고 마개 가장자리에 마른 잉크 얼룩이 묻어 있습니다.$fd$ where item_book_id = 'a92d8af5-78cc-9d19-738f-9b6897f0f6d7' and name = $fd$단종 잉크병$fd$;
update public.badges set form_description = $fd$마스킹테이프 롤이 가지런히 누운 납작한 상자입니다. 뚜껑이 열려 있고 맨 위 롤의 끝이 살짝 접혀 들떠 있습니다.$fd$ where item_book_id = 'a92d8af5-78cc-9d19-738f-9b6897f0f6d7' and name = $fd$마스킹테이프 상자$fd$;
update public.badges set form_description = $fd$흰 바탕에 파란 색이 칠해진 직사각형 나무 간판입니다. 가장자리 칠이 벗겨졌고 네 모서리에 못 구멍이 나 있습니다.$fd$ where item_book_id = 'a92d8af5-78cc-9d19-738f-9b6897f0f6d7' and name = $fd$명성문방구 간판$fd$;
update public.badges set form_description = $fd$노란 육각 연필이 가지런히 줄지어 누워 있습니다. 모두 새것이라 끝이 깎이지 않았고 맨 끝 연필이 약간 어긋났습니다.$fd$ where item_book_id = 'a92d8af5-78cc-9d19-738f-9b6897f0f6d7' and name = $fd$연필 한 다스$fd$;
update public.badges set form_description = $fd$투명한 작은 플라스틱 분무기입니다. 노즐 끝에 마른 물자국이 겹쳐 있고 병 아래쪽에 물이 조금 남았습니다.$fd$ where item_book_id = 'cd526b91-4088-303d-f157-2db59e663f4d' and name = $fd$유리 세정 분무기$fd$;
update public.badges set form_description = $fd$접힌 회색 극세사 수건입니다. 보풀이 일었고 끝단 솔기가 풀려 있으며 가장자리에 물때 얼룩이 번졌습니다.$fd$ where item_book_id = 'cd526b91-4088-303d-f157-2db59e663f4d' and name = $fd$극세사 수건$fd$;
update public.badges set form_description = $fd$작은 사각 플라스틱 팻말입니다. 앞면에 굵은 음각 무늬가 있고 뒷면에 접착 띠가 붙었으며 모서리가 살짝 들떴습니다.$fd$ where item_book_id = 'cd526b91-4088-303d-f157-2db59e663f4d' and name = $fd$칸 번호 팻말$fd$;
update public.badges set form_description = $fd$목이 꺾이는 작은 클립 조명입니다. 마디가 구부러져 있고 전선이 흰 테이프로 묶여 있으며 갓 가장자리가 그을렸습니다.$fd$ where item_book_id = 'cd526b91-4088-303d-f157-2db59e663f4d' and name = $fd$꺾어 둔 칸 조명$fd$;
update public.badges set form_description = $fd$놋쇠빛 작은 열쇠입니다. 고리 구멍이 둥글고 톱니가 거칠게 파여 있으며 표면이 닳아 반질거립니다.$fd$ where item_book_id = 'cd526b91-4088-303d-f157-2db59e663f4d' and name = $fd$칸 열쇠$fd$;
update public.badges set form_description = $fd$작은 직사각형 종이 이름표입니다. 모서리에 접착 자국이 남아 있고 윗부분이 살짝 말려 있습니다.$fd$ where item_book_id = 'cd526b91-4088-303d-f157-2db59e663f4d' and name = $fd$손글씨 이름표$fd$;
update public.badges set form_description = $fd$스테인리스 보온병 뚜껑을 컵처럼 뒤집은 모양입니다. 겉면이 찌그러졌고 안쪽 바닥에 긁힌 흠이 있습니다.$fd$ where item_book_id = '31b5587e-d58e-3630-06d9-8a7665ba2ad0' and name = $fd$보온병 뚜껑 컵$fd$;
update public.badges set form_description = $fd$반으로 접힌 작은 메모지입니다. 가운데 접힌 줄이 선명하고 한쪽 귀퉁이가 살짝 구겨져 있습니다.$fd$ where item_book_id = '79ab7cbd-a18e-d9d3-d340-940bece93f32' and name = $fd$세제 채움 메모$fd$;
update public.badges set form_description = $fd$귤만 한 둥근 털실 뭉치입니다. 겉실 가닥이 느슨하게 삐져나와 있습니다.$fd$ where item_book_id = '75cb518f-77c2-b1af-4d11-e0843c7517e5' and name = $fd$털실 한 뭉치$fd$;
update public.badges set form_description = $fd$둥글납작하게 감긴 노란 줄자입니다. 줄이 조금 풀려 나와 있고 눈금 몇 칸이 닳아 흐려져 있습니다.$fd$ where item_book_id = '75cb518f-77c2-b1af-4d11-e0843c7517e5' and name = $fd$줄자$fd$;
update public.badges set form_description = $fd$머리띠가 벌어진 채 놓인 검은 헤드폰입니다. 귀 덮개의 천이 조금 눌려 있고 이음새는 매끈하게 닳았습니다.$fd$ where item_book_id = '0b57f851-6ed6-9ab4-5ad6-17a5732dd802' and name = $fd$벗어 놓은 헤드폰$fd$;
update public.badges set form_description = $fd$흰 네모 기계입니다. 아래쪽에 투명한 물통이 끼워져 있고 바닥에 물이 조금 고여 있습니다.$fd$ where item_book_id = '4dbe2c2a-2a77-e70d-4790-0770b60050fb' and name = $fd$제습기$fd$;
update public.badges set form_description = $fd$가늘고 긴 대나무 뜨개바늘이 털실 뭉치에 꽂혀 있습니다. 끝이 닳아 둥글게 변해 있습니다.$fd$ where item_book_id = '75cb518f-77c2-b1af-4d11-e0843c7517e5' and name = $fd$뜨개바늘$fd$;
update public.badges set form_description = $fd$눌러 다진 회색 털로 만든 탁구공만 한 공입니다. 겉이 단단하고 군데군데 보풀이 일어나 있습니다.$fd$ where item_book_id = '75cb518f-77c2-b1af-4d11-e0843c7517e5' and name = $fd$건조기 볼$fd$;
update public.badges set form_description = $fd$얕은 흰 플라스틱 바구니에 색과 무늬가 제각각인 양말이 수북하게 담겨 있습니다. 한쪽 테두리에 금이 가 있습니다.$fd$ where item_book_id = '9b6ac9a0-f665-923f-e778-3b82f6eb5bbe' and name = $fd$양말 바구니$fd$;
update public.badges set form_description = $fd$스프링으로 묶인 연습장이 펼쳐져 있습니다. 앞쪽 장마다 연필 자국이 빽빽하고 모서리가 살짝 말려 있습니다.$fd$ where item_book_id = '0b57f851-6ed6-9ab4-5ad6-17a5732dd802' and name = $fd$연습장$fd$;
update public.badges set form_description = $fd$안쪽 털이 보송하게 일어난 외짝 수면양말입니다. 발목 고무줄이 헐렁하게 늘어나 있습니다.$fd$ where item_book_id = '9b6ac9a0-f665-923f-e778-3b82f6eb5bbe' and name = $fd$한 짝만 남은 수면양말$fd$;
update public.badges set form_description = $fd$길쭉한 흰 형광등 관이 누워 있습니다. 양 끝 쇠 마개에 검은 그을음이 번져 있습니다.$fd$ where item_book_id = '5fe3f8eb-970b-9847-dbfa-9773337c27d5' and name = $fd$형광등 한 줄$fd$;
