update public.badges set form_description = $fd$모서리가 둥글게 닳은 두툼한 문제집입니다. 표지가 약간 휘어 있고 뒤쪽 장은 깨끗한 상태입니다.$fd$ where item_book_id = '0b57f851-6ed6-9ab4-5ad6-17a5732dd802' and name = $fd$문제집 한 권$fd$;
update public.badges set form_description = $fd$마디 길이만큼 닳은 노란 연필입니다. 깎인 면에 흑연이 은색으로 반짝이고 나무 몸통이 갈라져 있습니다.$fd$ where item_book_id = 'e6399dcb-6a46-48e5-3251-7a1493d5f55d' and name = $fd$몽당연필$fd$;
update public.badges set form_description = $fd$뚜껑이 밀려 열린 하얀 플라스틱 세제통입니다. 가득 찬 푸른 액체가 입구에서 찰랑이고 옆면에 얼룩이 있습니다.$fd$ where item_book_id = '9b6ac9a0-f665-923f-e778-3b82f6eb5bbe' and name = $fd$세제통$fd$;
update public.badges set form_description = $fd$가는 허리의 유리 모래시계입니다. 위쪽 칸의 모래가 절반쯤 내려갔고 나무 받침에 흠집이 있습니다.$fd$ where item_book_id = '5fe3f8eb-970b-9847-dbfa-9773337c27d5' and name = $fd$모래시계$fd$;
update public.badges set form_description = $fd$휴대폰보다 조금 작은 검은 무전기입니다. 짧은 안테나가 살짝 휘었고 몸통 모서리 칠이 벗겨졌습니다.$fd$ where item_book_id = '27a42766-401c-4b7e-a2f5-ac39de9a3319' and name = $fd$무전기$fd$;
update public.badges set form_description = $fd$투명 테이프 조각이 종이 윗단을 붙잡고 있습니다. 모서리가 살짝 말려 올라오고 누렇게 변했습니다.$fd$ where item_book_id = 'ae9d96c9-a453-432d-a4b8-c9d4262f4937' and name = $fd$장부 테이프$fd$;
update public.badges set form_description = $fd$반듯하게 접힌 작은 쪽지입니다. 테이프 자국이 남은 모서리가 약간 말려 있습니다.$fd$ where item_book_id = '79ab7cbd-a18e-d9d3-d340-940bece93f32' and name = $fd$수리 목요일 메모$fd$;
update public.badges set form_description = $fd$흰 철제 접이식 건조대입니다. 가로대가 여러 줄 나란히 펴져 있고 다리 쪽에 녹이 조금 슬었습니다.$fd$ where item_book_id = '4dbe2c2a-2a77-e70d-4790-0770b60050fb' and name = $fd$건조대$fd$;
update public.badges set form_description = $fd$자루가 긴 대걸레입니다. 끝에 달린 회색 올이 길게 늘어져 있고 자루 아래쪽이 닳았습니다.$fd$ where item_book_id = '4dbe2c2a-2a77-e70d-4790-0770b60050fb' and name = $fd$대걸레$fd$;
update public.badges set form_description = $fd$작은 회색 플라스틱 휴지통입니다. 바닥에 회색 보풀이 보드랍게 깔려 있고 가장자리가 조금 찌그러졌습니다.$fd$ where item_book_id = '9b6ac9a0-f665-923f-e778-3b82f6eb5bbe' and name = $fd$작은 휴지통$fd$;
update public.badges set form_description = $fd$가장자리가 누렇게 바랜 종이입니다. 결이 거칠고 가벼워 보이며 귀퉁이가 조금 찢어져 있습니다.$fd$ where item_book_id = 'e6399dcb-6a46-48e5-3251-7a1493d5f55d' and name = $fd$누렇게 변색된 종이$fd$;
update public.badges set form_description = $fd$성냥갑만 한 작은 나무 도장입니다. 바닥에 등대 모양이 새겨져 있고 가장자리에 붉은 잉크가 묻어 있습니다.$fd$ where item_book_id = '9b6ac9a0-f665-923f-e778-3b82f6eb5bbe' and name = $fd$등대 모양 도장$fd$;
update public.badges set form_description = $fd$바퀴 달린 철제 빨래 카트가 접힌 채 있습니다. 바퀴 중 일부가 비뚤게 달려 있고 철망 가장자리가 휘었습니다.$fd$ where item_book_id = '2ca772e9-1ef9-938a-f793-b8e0e75c4914' and name = $fd$빨래 카트$fd$;
update public.badges set form_description = $fd$굵은 검은 매직펜입니다. 뚜껑이 벗겨져 있고 펜 끝에 잉크가 말라붙어 있습니다.$fd$ where item_book_id = '2ca772e9-1ef9-938a-f793-b8e0e75c4914' and name = $fd$수리 중 펜$fd$;
update public.badges set form_description = $fd$작은 사각 자석입니다. 표면에 검은 붓 자국이 가득하고 모서리가 약간 닳았습니다.$fd$ where item_book_id = '2ca772e9-1ef9-938a-f793-b8e0e75c4914' and name = $fd$손글씨 자석$fd$;
update public.badges set form_description = $fd$솔이 짧게 닳은 작은 빗자루입니다. 나무 자루 끝에 구멍이 뚫려 있고 솔이 한쪽으로 쏠려 있습니다.$fd$ where item_book_id = '2ca772e9-1ef9-938a-f793-b8e0e75c4914' and name = $fd$손빗자루$fd$;
update public.badges set form_description = $fd$둥근 유리문이 달린 흰 건조기입니다. 문 가장자리에 때가 앉아 둥글게 닳았고 유리가 약간 뿌옇습니다.$fd$ where item_book_id = '2ca772e9-1ef9-938a-f793-b8e0e75c4914' and name = $fd$3번 건조기$fd$;
update public.badges set form_description = $fd$가는 흰 줄이 팽팽하게 매여 있습니다. 양 끝이 고리에 묶여 있고 가운데가 약간 바랬습니다.$fd$ where item_book_id = '9b6ac9a0-f665-923f-e778-3b82f6eb5bbe' and name = $fd$빨랫줄$fd$;
update public.badges set form_description = $fd$가는 줄에 색이 다른 양말이 나란히 걸려 있습니다. 모두 발끝이 아래로 늘어졌고 일부는 뒤집혀 있습니다.$fd$ where item_book_id = '9b6ac9a0-f665-923f-e778-3b82f6eb5bbe' and name = $fd$한 줄로 걸린 양말$fd$;
update public.badges set form_description = $fd$같은 무늬의 양말 짝이 발목을 맞대어 포개져 있습니다. 늘어진 정도까지 닮았고 뒤꿈치가 약간 닳았습니다.$fd$ where item_book_id = '9b6ac9a0-f665-923f-e778-3b82f6eb5bbe' and name = $fd$짝을 찾은 양말$fd$;
update public.badges set form_description = $fd$얇은 종이 벽걸이 달력입니다. 장이 반쯤 넘겨져 있고 칸마다 격자가 나뉘어 있으며 모서리가 접혔습니다.$fd$ where item_book_id = '9b6ac9a0-f665-923f-e778-3b82f6eb5bbe' and name = $fd$달력$fd$;
update public.badges set form_description = $fd$은색 금속 스톱워치입니다. 둥근 문자판 위 바늘이 멈춰 있고 윗부분 버튼의 도금이 벗겨졌습니다.$fd$ where item_book_id = '5fe3f8eb-970b-9847-dbfa-9773337c27d5' and name = $fd$스톱워치$fd$;
update public.badges set form_description = $fd$얇은 남색 점퍼가 지퍼를 반쯤 연 채 구겨져 있습니다. 소매 끝이 올이 풀려 하얗게 닳았습니다.$fd$ where item_book_id = '5fe3f8eb-970b-9847-dbfa-9773337c27d5' and name = $fd$점퍼$fd$;
update public.badges set form_description = $fd$가운데는 눅눅하고 가장자리만 마른 회색 수건입니다. 반으로 접혀 있고 올이 군데군데 풀려 있습니다.$fd$ where item_book_id = '5fe3f8eb-970b-9847-dbfa-9773337c27d5' and name = $fd$덜 마른 수건$fd$;
update public.badges set form_description = $fd$포개 쓰는 흰 플라스틱 바구니입니다. 손잡이 쪽이 닳아 허옇게 바랬고 옆면에 긁힌 자국이 있습니다.$fd$ where item_book_id = '5fe3f8eb-970b-9847-dbfa-9773337c27d5' and name = $fd$빨래 바구니$fd$;
update public.badges set form_description = $fd$흰 플라스틱 다이얼 타이머입니다. 둥근 돌림판이 중간쯤 돌아가 있고 모서리가 누렇게 변했습니다.$fd$ where item_book_id = '5fe3f8eb-970b-9847-dbfa-9773337c27d5' and name = $fd$타이머$fd$;
update public.badges set form_description = $fd$얇은 플라스틱 안내판입니다. 모서리가 말려 올라갔고 표면이 색 줄로 칸마다 나뉘어 있습니다.$fd$ where item_book_id = '5fe3f8eb-970b-9847-dbfa-9773337c27d5' and name = $fd$건조 코스 안내판$fd$;
update public.badges set form_description = $fd$눈금이 반쯤 지워진 투명한 플라스틱 컵입니다. 입구에 주둥이가 나 있고 바닥에 세제 자국이 말라붙었습니다.$fd$ where item_book_id = '5fe3f8eb-970b-9847-dbfa-9773337c27d5' and name = $fd$세제 계량컵$fd$;
update public.badges set form_description = $fd$모서리가 둥글게 닳은 두꺼운 노트입니다. 표지가 휘었고 책등 실이 조금 풀려 있습니다.$fd$ where item_book_id = '79ab7cbd-a18e-d9d3-d340-940bece93f32' and name = $fd$닳은 노트$fd$;
update public.badges set form_description = $fd$상판이 펴진 흰 접이식 테이블입니다. 상판 끝이 눌려 살짝 휘었고 다리가 약간 기울었습니다.$fd$ where item_book_id = '79ab7cbd-a18e-d9d3-d340-940bece93f32' and name = $fd$접이식 테이블$fd$;
update public.badges set form_description = $fd$검은 몸통의 만년필 뚜껑이 빠져 있습니다. 금속 펜촉이 한쪽으로 닳았고 몸통에 잉크 얼룩이 있습니다.$fd$ where item_book_id = '79ab7cbd-a18e-d9d3-d340-940bece93f32' and name = $fd$만년필$fd$;
update public.badges set form_description = $fd$속지를 찢어 낸 작은 종이 쪽입니다. 가장자리가 들쭉날쭉하고 접힌 자국이 가로로 나 있습니다.$fd$ where item_book_id = '79ab7cbd-a18e-d9d3-d340-940bece93f32' and name = $fd$탈수 약함 메모$fd$;
update public.badges set form_description = $fd$빈 깡통에 굵기가 제각각인 펜이 여러 자루 꽂혀 있습니다. 깡통 겉이 우그러졌고 페인트가 벗겨졌습니다.$fd$ where item_book_id = '79ab7cbd-a18e-d9d3-d340-940bece93f32' and name = $fd$펜 꽂은 깡통$fd$;
update public.badges set form_description = $fd$검은 쇠 집게 클립이 종이 가장자리를 물고 있습니다. 물린 종이에 얇은 주름이 졌고 클립 칠이 벗겨졌습니다.$fd$ where item_book_id = '79ab7cbd-a18e-d9d3-d340-940bece93f32' and name = $fd$클립$fd$;
update public.badges set form_description = $fd$직육면체 종이 티슈 상자입니다. 윗면 구멍으로 티슈가 접혀 삐져나왔고 상자 모서리가 눌려 있습니다.$fd$ where item_book_id = '79ab7cbd-a18e-d9d3-d340-940bece93f32' and name = $fd$각티슈$fd$;
update public.badges set form_description = $fd$고리에 꿴 작은 카드 묶음이 부채처럼 펼쳐져 있습니다. 카드 모서리가 둥글게 닳았고 구멍 둘레가 해졌습니다.$fd$ where item_book_id = '0b57f851-6ed6-9ab4-5ad6-17a5732dd802' and name = $fd$단어장$fd$;
update public.badges set form_description = $fd$투명하고 얇은 플라스틱 파일입니다. 모서리가 하얗게 긁혔고 안에 종이가 여러 장 들어 있습니다.$fd$ where item_book_id = '0b57f851-6ed6-9ab4-5ad6-17a5732dd802' and name = $fd$투명 파일$fd$;
update public.badges set form_description = $fd$납작한 검은 천 케이스의 지퍼가 열려 있습니다. 안쪽 회색 융이 헤드폰 모양으로 눌려 있고 지퍼 끝이 해졌습니다.$fd$ where item_book_id = '0b57f851-6ed6-9ab4-5ad6-17a5732dd802' and name = $fd$헤드폰 케이스$fd$;
update public.badges set form_description = $fd$가늘게 말린 원통형 회색 스펀지 귀마개 쌍입니다. 가장자리가 조금 찢어져 있고 먼지가 묻어 있습니다.$fd$ where item_book_id = '0b57f851-6ed6-9ab4-5ad6-17a5732dd802' and name = $fd$귀마개$fd$;
update public.badges set form_description = $fd$책 쪽을 덮을 만한 얇은 붉은색 투명 시트입니다. 모서리가 둥글게 잘려 있고 가장자리가 조금 휘었습니다.$fd$ where item_book_id = '0b57f851-6ed6-9ab4-5ad6-17a5732dd802' and name = $fd$빨간 시트$fd$;
update public.badges set form_description = $fd$딱딱해 보이는 회색 플라스틱 의자입니다. 다리 끝 고무가 닳았고 앉는 면에 긁힌 자국이 있습니다.$fd$ where item_book_id = '75cb518f-77c2-b1af-4d11-e0843c7517e5' and name = $fd$딱딱한 플라스틱 의자$fd$;
update public.badges set form_description = $fd$날이 짧고 끝이 새 부리처럼 뾰족한 작은 가위입니다. 은색 날이 무디게 닳았고 고리 손잡이가 열려 있습니다.$fd$ where item_book_id = '75cb518f-77c2-b1af-4d11-e0843c7517e5' and name = $fd$실 가위$fd$;
update public.badges set form_description = $fd$성냥갑만 한 은색 금속 카운터입니다. 윗면에 작은 둥근 누름 버튼이 있고 표면에 긁힘이 있습니다.$fd$ where item_book_id = '75cb518f-77c2-b1af-4d11-e0843c7517e5' and name = $fd$단수 카운터$fd$;
update public.badges set form_description = $fd$물을 먹어 묵직하게 처진 뜨개 방석입니다. 가장자리가 축 늘어졌고 귀퉁이 올이 풀려 있습니다.$fd$ where item_book_id = '75cb518f-77c2-b1af-4d11-e0843c7517e5' and name = $fd$빨아 둔 방석$fd$;
update public.badges set form_description = $fd$둥근 유리문이 달린 흰 드럼 세탁기입니다. 문 안쪽 드럼이 돌아가는 중이고 문틀에 얼룩이 있습니다.$fd$ where item_book_id = '4dbe2c2a-2a77-e70d-4790-0770b60050fb' and name = $fd$한 대만 도는 세탁기$fd$;
update public.badges set form_description = $fd$올이 성긴 흰 그물 주머니입니다. 지퍼가 반쯤 열려 있고 귀퉁이 박음질이 풀렸습니다.$fd$ where item_book_id = '4dbe2c2a-2a77-e70d-4790-0770b60050fb' and name = $fd$세탁망$fd$;
update public.badges set form_description = $fd$돌기가 촘촘히 돋은 하늘색 고무공이 나란히 놓여 있습니다. 말랑하게 눌려 있고 색이 군데군데 바랬습니다.$fd$ where item_book_id = '4dbe2c2a-2a77-e70d-4790-0770b60050fb' and name = $fd$세탁볼$fd$;
update public.badges set form_description = $fd$끈끈한 종이가 감긴 원통 롤러에 짧은 자루가 달렸습니다. 겉 종이가 뜯겨 있고 보풀이 붙어 있습니다.$fd$ where item_book_id = '4dbe2c2a-2a77-e70d-4790-0770b60050fb' and name = $fd$보풀 롤러$fd$;
update public.badges set form_description = $fd$파란 플라스틱 양동이입니다. 테두리가 하얗게 바랬고 철사 손잡이가 한쪽으로 기울어 있습니다.$fd$ where item_book_id = '4dbe2c2a-2a77-e70d-4790-0770b60050fb' and name = $fd$양동이$fd$;
update public.badges set form_description = $fd$하늘색 고무 슬리퍼가 나란히 놓여 있습니다. 뒤꿈치 쪽이 평평하게 닳았고 바닥에 물기가 번졌습니다.$fd$ where item_book_id = '4dbe2c2a-2a77-e70d-4790-0770b60050fb' and name = $fd$슬리퍼$fd$;
update public.badges set form_description = $fd$문고본 크기의 작은 책이 펼쳐져 있습니다. 쪽 모서리가 삼각형으로 접혔고 책등이 하얗게 갈라졌습니다.$fd$ where item_book_id = 'e6399dcb-6a46-48e5-3251-7a1493d5f55d' and name = $fd$귀퉁이 접힌 책$fd$;
update public.badges set form_description = $fd$납작하게 마른 갈색 나뭇잎입니다. 잎맥만 또렷하게 남았고 가장자리가 바스라져 있습니다.$fd$ where item_book_id = 'e6399dcb-6a46-48e5-3251-7a1493d5f55d' and name = $fd$책갈피로 쓰인 말린 나뭇잎$fd$;
update public.badges set form_description = $fd$가느다란 은색 샤프펜슬입니다. 머리 쪽 지우개가 닳았고 촉 끝에 심이 조금 나와 있습니다.$fd$ where item_book_id = 'e6399dcb-6a46-48e5-3251-7a1493d5f55d' and name = $fd$샤프펜슬$fd$;
update public.badges set form_description = $fd$접으면 납작해지는 작은 나무 독서대가 펼쳐져 있습니다. 경사진 면이 비스듬하고 경첩이 헐겁습니다.$fd$ where item_book_id = 'e6399dcb-6a46-48e5-3251-7a1493d5f55d' and name = $fd$독서대$fd$;
update public.badges set form_description = $fd$필통에 들어갈 길이의 투명한 플라스틱 자입니다. 눈금이 가장자리에만 있고 표면에 잔 긁힘이 있습니다.$fd$ where item_book_id = 'e6399dcb-6a46-48e5-3251-7a1493d5f55d' and name = $fd$투명 자$fd$;
update public.badges set form_description = $fd$비누 조각만 한 수정테이프입니다. 흰 띠가 끝에서 조금 풀려 나와 있고 몸통 플라스틱이 긁혔습니다.$fd$ where item_book_id = 'e6399dcb-6a46-48e5-3251-7a1493d5f55d' and name = $fd$수정테이프$fd$;
update public.badges set form_description = $fd$작은 금속 연필깎이입니다. 구멍 옆으로 얇은 나무 부스러기가 말려 나와 있고 칼날이 무뎌졌습니다.$fd$ where item_book_id = 'e6399dcb-6a46-48e5-3251-7a1493d5f55d' and name = $fd$연필깎이$fd$;
update public.badges set form_description = $fd$짙은 초록 몸통의 작은 손전등입니다. 칠이 군데군데 벗겨졌고 머리 쪽 렌즈에 먼지가 앉았습니다.$fd$ where item_book_id = '27a42766-401c-4b7e-a2f5-ac39de9a3319' and name = $fd$작은 손전등$fd$;
update public.badges set form_description = $fd$얇은 종이를 겹쳐 만든 작은 일력이 받침에 서 있습니다. 앞쪽 장이 가볍게 말려 있고 받침 모서리가 닳았습니다.$fd$ where item_book_id = '27a42766-401c-4b7e-a2f5-ac39de9a3319' and name = $fd$일력$fd$;
update public.badges set form_description = $fd$무명으로 짠 네모난 보자기가 접혀 있습니다. 여러 번 빨아 가장자리가 보드랍고 올이 약간 풀렸습니다.$fd$ where item_book_id = '27a42766-401c-4b7e-a2f5-ac39de9a3319' and name = $fd$보자기$fd$;
update public.badges set form_description = $fd$집게로 물리는 작은 작업등입니다. 목이 구부러져 있고 갓 안쪽 도장이 벗겨졌습니다.$fd$ where item_book_id = '27a42766-401c-4b7e-a2f5-ac39de9a3319' and name = $fd$작업등$fd$;
update public.badges set form_description = $fd$둥근 손거울입니다. 테두리 쇠가 닳아 도금이 연해졌고 거울면 가장자리에 얼룩이 번졌습니다.$fd$ where item_book_id = '27a42766-401c-4b7e-a2f5-ac39de9a3319' and name = $fd$손거울$fd$;
update public.badges set form_description = $fd$둥근 유리 전구입니다. 쓰지 않아 유리 안쪽이 맑고 금속 꼭지가 반짝입니다.$fd$ where item_book_id = '27a42766-401c-4b7e-a2f5-ac39de9a3319' and name = $fd$여분 전구$fd$;
update public.badges set form_description = $fd$이가 한쪽으로 기운 쇠 열쇠입니다. 머리 구멍 안쪽이 반질반질하고 몸통에 녹이 조금 슬었습니다.$fd$ where item_book_id = '27a42766-401c-4b7e-a2f5-ac39de9a3319' and name = $fd$등대 열쇠$fd$;
update public.badges set form_description = $fd$주머니가 여러 개 달린 회색 조끼입니다. 오른쪽 아래 주머니만 밑이 두툼하게 늘어났고 단추가 헐거워졌습니다.$fd$ where item_book_id = '27a42766-401c-4b7e-a2f5-ac39de9a3319' and name = $fd$작업 조끼$fd$;
update public.badges set form_description = $fd$뚜껑 없는 투명 플라스틱 통입니다. 바닥에 동전이 겹겹이 깔렸고 옆면이 뿌옇게 긁혔습니다.$fd$ where item_book_id = 'ae9d96c9-a453-432d-a4b8-c9d4262f4937' and name = $fd$비상 통$fd$;
update public.badges set form_description = $fd$얇은 장부가 펼쳐져 있습니다. 칸이 나뉜 줄이 촘촘하고 귀퉁이가 닳아 있습니다.$fd$ where item_book_id = 'ae9d96c9-a453-432d-a4b8-c9d4262f4937' and name = $fd$통 옆의 장부$fd$;
update public.badges set form_description = $fd$작은 회색 전자계산기입니다. 자주 누른 키의 표면이 반쯤 닳았고 윗부분 태양전지판이 약간 긁혔습니다.$fd$ where item_book_id = 'ae9d96c9-a453-432d-a4b8-c9d4262f4937' and name = $fd$전자계산기$fd$;
update public.badges set form_description = $fd$은색 둥근 동전입니다. 테두리에 가는 홈이 빙 돌려 있고 표면이 닳아 윤이 흐려져 있습니다.$fd$ where item_book_id = 'ae9d96c9-a453-432d-a4b8-c9d4262f4937' and name = $fd$500원짜리$fd$;
update public.badges set form_description = $fd$얇은 플라스틱 눈금자입니다. 한쪽 모서리가 닳아 둥글게 무뎌졌고 눈금이 흐려진 곳이 있습니다.$fd$ where item_book_id = 'ae9d96c9-a453-432d-a4b8-c9d4262f4937' and name = $fd$눈금자$fd$;
update public.badges set form_description = $fd$연한 갈색 고무 골무입니다. 바깥에 가는 돌기가 촘촘히 돋았고 입구가 약간 늘어났습니다.$fd$ where item_book_id = 'ae9d96c9-a453-432d-a4b8-c9d4262f4937' and name = $fd$고무 골무$fd$;
update public.badges set form_description = $fd$구리빛 동전 여러 개가 포개져 있습니다. 가장자리마다 때가 얇게 앉았고 일부는 색이 어둡습니다.$fd$ where item_book_id = 'ae9d96c9-a453-432d-a4b8-c9d4262f4937' and name = $fd$10원짜리 잔돈$fd$;
update public.badges set form_description = $fd$구리빛 동전이 놓여 있습니다. 많이 만져진 면만 유난히 반질하고 테두리에 얼룩이 앉았습니다.$fd$ where item_book_id = 'ae9d96c9-a453-432d-a4b8-c9d4262f4937' and name = $fd$돌아온 한 닢$fd$;
update public.badges set form_description = $fd$코가 촘촘한 네모난 뜨개 방석입니다. 모든 귀퉁이가 둥글게 말려 올라갔고 올이 삐져나왔습니다.$fd$ where item_book_id = '75cb518f-77c2-b1af-4d11-e0843c7517e5' and name = $fd$뜨개 방석$fd$;
update public.badges set form_description = $fd$성냥갑만 한 사각 철판입니다. 모서리에 나사 구멍이 뚫려 있고 표면이 녹으로 얼룩졌습니다.$fd$ where item_book_id = '2ca772e9-1ef9-938a-f793-b8e0e75c4914' and name = $fd$철제 명판$fd$;
update public.badges set form_description = $fd$끝이 십자로 갈라진 드라이버입니다. 손잡이 고무가 한쪽만 하얗게 닳았고 쇠 막대에 기름때가 묻었습니다.$fd$ where item_book_id = '2ca772e9-1ef9-938a-f793-b8e0e75c4914' and name = $fd$십자 드라이버$fd$;
update public.badges set form_description = $fd$지퍼가 끝까지 잠긴 작은 천 주머니입니다. 안에 든 공구 모양이 겉으로 불룩하게 드러나고 귀퉁이가 해졌습니다.$fd$ where item_book_id = '2ca772e9-1ef9-938a-f793-b8e0e75c4914' and name = $fd$공구 주머니$fd$;
update public.badges set form_description = $fd$윗부분에 쇠 집게가 달린 얇은 나무판입니다. 집게에 종이가 반듯하게 물려 있고 판 모서리가 닳았습니다.$fd$ where item_book_id = '2ca772e9-1ef9-938a-f793-b8e0e75c4914' and name = $fd$클립보드$fd$;
commit;
